package rsfost.ba_metronome;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BaMetronomePluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(BaMetronomePlugin.class);
        RuneLite.main(args);
    }
}

package rsfost.ba_metronome;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("ba-metronome")
public interface BaMetronomeConfig extends Config
{
    @ConfigSection(
        name = "Healer",
        description = "Configuration for the healer role",
        position = 100,
        closedByDefault = false
    )
    String healer = "healer";

    @ConfigItem(
        keyName = "feedVolume",
        name = "Feed volume",
        description = "Volume of the sound played when food is used on a penance healer. Set to 0 to disable.",
        position = 1,
        section = healer
    )
    @Range(
        min = 0,
        max = 127
    )
    default int feedVolume()
    {
        return 127;
    }

    @ConfigItem(
        keyName = "beatsAfterFeed",
        name = "Beats after feed",
        description = "How many further beats the metronome plays after a feed before falling silent. "
            + "Set to 0 to hear the feed tick on its own.",
        position = 2,
        section = healer
    )
    @Range(
        min = 0,
        max = 20
    )
    default int beatsAfterFeed()
    {
        return 3;
    }

    @ConfigItem(
        keyName = "distinctWrongFoodSound",
        name = "Distinct wrong food sound",
        description = "Play a different sound when the game rejects the food as the wrong type. "
            + "When off, a wrong food sounds the same as a good one.",
        position = 3,
        section = healer
    )
    default boolean distinctWrongFoodSound()
    {
        return true;
    }
}

package rsfost.ba_metronome;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.SoundEffectID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

/**
 * Sound effects for the healer role: detects the exact game tick the local player's poisoned food
 * is used on a penance healer and beats a metronome from it.
 */
@Slf4j
class HealerSoundEffects
{
    private static final Set<Integer> PENANCE_HEALER_NPC_IDS = Set.of(
        NpcID.BARBASSAULT_PEN_HEALER_LV1,
        NpcID.BARBASSAULT_PEN_HEALER_LV2,
        NpcID.BARBASSAULT_PEN_HEALER_LV3,
        NpcID.BARBASSAULT_PEN_HEALER_LV4,
        NpcID.BARBASSAULT_PEN_HEALER_LV5,
        NpcID.BARBASSAULT_PEN_HEALER_LV6,
        NpcID.BARBASSAULT_PEN_HEALER_LV7,
        NpcID.BARBASSAULT_PEN_HEALER_LV8,
        NpcID.BARBASSAULT_PEN_HEALER_LV9
    );

    private static final Set<Integer> HEALER_FOOD_ITEM_IDS = Set.of(
        ItemID.BARBASSAULT_POISION_01,
        ItemID.BARBASSAULT_POISION_02,
        ItemID.BARBASSAULT_POISION_03
    );

    private static final String WRONG_FOOD_MESSAGE = "wrong type of poisoned food";

    private static final String DESTROY_OPTION = "Destroy";

    // How long a destroy stays suppressed after its click.
    private static final int DESTROY_SUPPRESS_TICKS = 5;

    // How long the healer clicked on stays worth reporting alongside a feed.
    private static final int CLICK_HINT_TICKS = 20;

    // Downbeat sounds
    private static final int FEED_SOUND = SoundEffectID.GE_INCREMENT_PLOP;
    private static final int WRONG_FOOD_SOUND = SoundEffectID.ZERO_DAMAGE_SPLAT;

    private final Client client;
    private final BaMetronomeConfig config;
    private final Metronome metronome;

    private final Map<Integer, Integer> foodCounts = new HashMap<>();

    // The most recent healer click
    private int clickedNpcIndex = -1;
    private int clickTick = -1;

    // Tick a food destroy was requested on, so its decrement is not mistaken for a feed
    private int destroyClickTick = -1;

    // Signals gathered during the current tick
    private int resolvedTick = -1;
    private int resolvedItemId = -1;
    private boolean foodSpentThisTick;
    private boolean wrongFoodMessageThisTick;

    @Inject
    HealerSoundEffects(Client client, BaMetronomeConfig config)
    {
        this.client = client;
        this.config = config;
        this.metronome = new Metronome(client);
    }

    void reset()
    {
        clickedNpcIndex = -1;
        clickTick = -1;
        destroyClickTick = -1;
        foodCounts.clear();
        metronome.reset();
    }

    /**
     * Notes context around the click. A use-on-healer click records which healer for the log;
     * destroying poisoned food arms a suppression window so the resulting inventory decrement is
     * not read as a feed. Neither is a precondition for detecting a feed.
     */
    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (event.isItemOp() && HEALER_FOOD_ITEM_IDS.contains(event.getItemId())
            && DESTROY_OPTION.equals(event.getMenuOption()))
        {
            destroyClickTick = client.getTickCount();
            return;
        }

        if (event.getMenuAction() != MenuAction.WIDGET_TARGET_ON_NPC)
        {
            return;
        }

        NPC target = event.getMenuEntry().getNpc();
        if (target == null || !PENANCE_HEALER_NPC_IDS.contains(target.getId()))
        {
            return;
        }

        Widget selected = client.getSelectedWidget();
        int selectedItemId = selected == null ? -1 : selected.getItemId();

        clickedNpcIndex = target.getIndex();
        clickTick = client.getTickCount();

        log.debug("Feed requested: healer index {} on tick {} (selected item hint {})",
            clickedNpcIndex, clickTick, selectedItemId);
    }

    /**
     * The food leaving the inventory is the authoritative signal that the use actually happened -
     * it is driven by the server and is specific to us, unlike the healer's animation which a
     * teammate's feed would also trigger.
     *
     * <p>A feed spends exactly one food. Losing more than one at once means the inventory was
     * cleared wholesale - wave end, leaving the game - which is not a feed and must not beat.
     */
    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() != InventoryID.INV)
        {
            return;
        }

        ItemContainer inventory = event.getItemContainer();
        int totalSpent = 0;
        int spentItemId = -1;

        for (int itemId : HEALER_FOOD_ITEM_IDS)
        {
            int newCount = inventory.count(itemId);
            Integer oldCount = foodCounts.put(itemId, newCount);

            if (oldCount != null && newCount < oldCount)
            {
                totalSpent += oldCount - newCount;
                spentItemId = itemId;
            }
        }

        if (totalSpent == 0)
        {
            return;
        }

        if (totalSpent > 1)
        {
            log.debug("Ignoring loss of {} poisoned foods at once - not a feed", totalSpent);
            return;
        }

        if (destroyClickTick != -1 && client.getTickCount() - destroyClickTick <= DESTROY_SUPPRESS_TICKS)
        {
            log.debug("Ignoring poisoned food lost to a destroy");
            destroyClickTick = -1;
            return;
        }

        foodSpentThisTick = true;
        resolvedItemId = spentItemId;
        resolvedTick = client.getTickCount();
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (event.getType() == ChatMessageType.GAMEMESSAGE
            && event.getMessage().toLowerCase().contains(WRONG_FOOD_MESSAGE))
        {
            wrongFoodMessageThisTick = true;
            resolvedTick = client.getTickCount();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        int downbeatSound = Metronome.NO_DOWNBEAT;

        if (foodSpentThisTick)
        {
            boolean correct = !wrongFoodMessageThisTick;
            downbeatSound = correct || !config.distinctWrongFoodSound()
                ? FEED_SOUND
                : WRONG_FOOD_SOUND;

            onFeedUsed(resolvedTick, resolvedItemId, correct);
            clickedNpcIndex = -1;
            clickTick = -1;
        }
        else if (clickedNpcIndex != -1 && client.getTickCount() - clickTick > CLICK_HINT_TICKS)
        {
            clickedNpcIndex = -1;
            clickTick = -1;
        }

        metronome.beat(downbeatSound, config.beatsAfterFeed(), config.feedVolume());

        resolvedTick = -1;
        resolvedItemId = -1;
        foodSpentThisTick = false;
        wrongFoodMessageThisTick = false;
    }

    private void onFeedUsed(int tick, int itemId, boolean correct)
    {
        log.debug("Fed healer index {} with item {} on tick {} (correct={},)",
            clickedNpcIndex, itemId, tick, correct);
    }
}

package rsfost.ba_metronome;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Owns the lifecycle of the per-role sound effect handlers. Each role keeps its own state and
 * event handlers in its own class; this class only wires them onto the event bus.
 */
@Slf4j
@PluginDescriptor(
    name = "BA Metronome",
    description = "Plays a metronome during various Barbarian Assault gameplay."
)
public class BaMetronomePlugin extends Plugin
{
    @Inject
    private EventBus eventBus;

    @Inject
    private HealerSoundEffects healerSoundEffects;

    @Inject
    private Client client;

    @Override
    protected void startUp() throws Exception
    {

    }

    @Override
    protected void shutDown() throws Exception
    {
        eventBus.unregister(healerSoundEffects);
        healerSoundEffects.reset();
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() == InterfaceID.BARBASSAULT_OVER_HEAL)
        {
            log.debug("Adding healerSoundEffects to event bus");
            healerSoundEffects.reset();
            eventBus.register(healerSoundEffects);
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        if (event.getVarbitId() == VarbitID.BARBASSAULT_AREAEXIT_PENDING && event.getValue() == 0)
        {
            log.debug("Removing healerSoundEffects from event bus");
            eventBus.unregister(healerSoundEffects);
        }
    }

    @Provides
    BaMetronomeConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BaMetronomeConfig.class);
    }
}

package rsfost.ba_metronome;

import net.runelite.api.Client;
import net.runelite.api.Preferences;
import net.runelite.api.SoundEffectID;

/**
 * A tick-driven beat that runs for a fixed number of beats after each downbeat and then falls
 * silent. The downbeat ticks and every beat after it tocks, so whatever triggered the downbeat
 * stands out audibly against the beats that follow it.
 */
class Metronome
{
    /** Downbeat sound meaning "this tick is not a downbeat", for ticks that only continue a run. */
    static final int NO_DOWNBEAT = -1;

    private final Client client;

    /** Beats left in the current run; 0 when silent. */
    private int beatsRemaining;

    Metronome(Client client)
    {
        this.client = client;
    }

    /**
     * Beats once for the current game tick. A downbeat restarts the run, so one landing inside an
     * existing run extends it rather than shortening it.
     *
     * @param downbeatSound      sound for this tick's downbeat, or {@link #NO_DOWNBEAT} if this
     *                           tick is not a downbeat. Letting the caller pick per downbeat lets
     *                           one run be started by events that must sound different.
     * @param beatsAfterDownbeat how long a run this downbeat starts. Read only when a downbeat
     *                           lands, not on every tick, so retuning it never truncates a run
     *                           already in progress.
     * @param volume             0-127; 0 silences the beat without disturbing the run
     */
    void beat(int downbeatSound, int beatsAfterDownbeat, int volume)
    {
        if (downbeatSound != NO_DOWNBEAT)
        {
            beatsRemaining = beatsAfterDownbeat;
            play(downbeatSound, volume);
        }
        else if (beatsRemaining > 0)
        {
            beatsRemaining--;
            play(SoundEffectID.GE_DECREMENT_PLOP, volume);
        }
    }

    void reset()
    {
        beatsRemaining = 0;
    }

    private void play(int soundEffectId, int volume)
    {
        if (volume <= 0)
        {
            return;
        }

        // playSoundEffect only honours the volume argument while the in-game volume is not muted,
        // so the preference has to be set around the call and restored afterwards. This is the same
        // workaround the official Metronome plugin uses.
        Preferences preferences = client.getPreferences();
        int previousVolume = preferences.getSoundEffectVolume();
        preferences.setSoundEffectVolume(volume);
        client.playSoundEffect(soundEffectId, volume);
        preferences.setSoundEffectVolume(previousVolume);
    }
}
